    }
  }
}

content.text:
/// Multimodal media inputs and capability discovery (gh-1844).
///
/// Shared by the `generate_image` / `generate_video` tools (CLI) and the
/// app's `MediaGateway`: reference images arrive as sandbox paths,
/// http(s) URLs, or base64 (raw or `data:` URLs), are validated against
/// the same guards the chat image pipeline uses (magic-byte sniffing from
/// `paste_image.dart`, a per-image byte cap, a per-request count cap),
/// and are rendered as OpenRouter `image_url` parts (data URLs for local
/// bytes, plain URLs passthrough).
///
/// Capability checks are CAPABILITY-DRIVEN, never model-name-driven
/// (gh-1844 AC5): a slot override may DECLARE its modalities
/// (`input: [text, image]`); OpenRouter endpoints can be DISCOVERED from
/// the `/api/v1/models` metadata (`architecture.input_modalities`);
/// endpoints with declared/discovered modalities that lack `image` reject
/// reference images with an actionable error BEFORE the generation call.
library;

import 'dart:convert';

import 'package:http/http.dart' as http;

import '../cli/paste_image.dart' show maxPasteImageBytes, sniffImageMime;
import '../env/execution_env.dart';
import 'generate_image.dart' show MediaException;

/// The maximum number of reference images one media call accepts
/// (OpenRouter allows up to 10 for image generation; the count cap keeps
/// request bodies sane for every dialect).
const maxMediaImageReferences = 10;

/// The default mime type for base64 inputs whose bytes carry no known
/// magic-byte signature.
const defaultImageMimeType = 'image/png';

/// One reference image argument, before resolution.
sealed class MediaImageInput {
  const MediaImageInput();

  /// A sandbox-relative (or absolute) local image path.
  const factory MediaImageInput.path(String path) = MediaImagePath;

  /// An http(s) URL the provider fetches itself.
  const factory MediaImageInput.url(String url) = MediaImageUrl;

  /// Raw base64 image data (mime sniffed from the decoded bytes).
  const factory MediaImageInput.base64(String base64) = MediaImageBase64;
}

/// Local sandbox path variant of [MediaImageInput].
final class MediaImagePath extends MediaImageInput {
  const MediaImagePath(this.path);

  /// The sandbox path to read.
  final String path;
}

/// http(s) URL variant of [MediaImageInput].
final class MediaImageUrl extends MediaImageInput {
  const MediaImageUrl(this.url);

  /// The URL passed through to the provider.
  final String url;
}

/// Raw base64 variant of [MediaImageInput].
final class MediaImageBase64 extends MediaImageInput {
  const MediaImageBase64(this.base64);

  /// The base64-encoded image bytes.
  final String base64;
}

/// Parses one tool-argument string into a [MediaImageInput]:
/// `data:` URLs, http(s) URLs, and bare base64 (a long base64-ish string
/// without path separators) become the matching variants; anything else is
/// a sandbox path.
MediaImageInput parseMediaImageInput(String raw) {
  final value = raw.trim();
  if (value.isEmpty) {
    throw MediaException('reference image entries must be non-empty');
  }
  if (value.startsWith('b64:')) {
    final data = value.substring(4);
    if (data.isEmpty) {
      throw MediaException(
        'b64: reference image is missing its payload',
      );
    }
    return MediaImageInput.base64(data);
  }
  if (value.startsWith('data:image/')) {
    final comma = value.indexOf(',');
    if (comma < 0) {
      throw MediaException('data URL reference image is missing its payload');
    }
    final payload = value.substring(comma + 1);
    if (payload.isEmpty) {
      throw MediaException('data URL reference image is missing its payload');
    }
    return MediaImageInput.base64(payload);
  }
  if (value.startsWith('http://') || value.startsWith('https://')) {
    return MediaImageInput.url(value);
  }
  // A bare base64 payload: long, no path separators, decodable.
  if (value.length >= 64 && !value.contains('/') && _looksLikeBase64(value)) {
    return MediaImageInput.base64(value);
  }
  return MediaImageInput.path(value);
}

bool _looksLikeBase64(String value) {
  for (final code in value.codeUnits) {
    final c = code;
    final ok =
        (c >= 0x41 && c <= 0x5A) || // A-Z
        (c >= 0x61 && c <= 0x7A) || // a-z
        (c >= 0x30 && c <= 0x39) || // 0-9
        c == 0x2B || // +
        c == 0x2F || // /
        c == 0x3D; // =
    if (!ok) return false;
  }
  return true;
}

/// A resolved reference image ready for the wire: either a provider-side
/// URL or a base64 data URL with a sniffed mime type.
final class ResolvedMediaImage {
  const ResolvedMediaImage._({required this.url, required this.mimeType});

  /// An http(s) URL the provider fetches.
  factory ResolvedMediaImage.remote(String url) =>
      ResolvedMediaImage._(url: url, mimeType: '');

  /// Base64 bytes inlined as a `data:` URL (mime sniffed from the bytes).
  factory ResolvedMediaImage.inline(List<int> bytes) {
    if (bytes.length > maxPasteImageBytes) {
      throw MediaException(
        'reference image is too large: ${bytes.length} bytes '
        '(cap $maxPasteImageBytes) — downscale the image',
      );
    }
    final mime = sniffImageMime(bytes) ?? defaultImageMimeType;
    return ResolvedMediaImage._(
      url: 'data:$mime;base64,${base64Encode(bytes)}',
      mimeType: mime,
    );
  }

  /// The `image_url` value sent to the provider.
  final String url;

  /// The sniffed mime type; empty for remote URLs (the provider sniffs).
  final String mimeType;

  /// The OpenRouter `input_references` / `frame_images` entry shape.
  Map<String, dynamic> toOpenRouterJson() => {
    'type': 'image_url',
    'image_url': {'url': url},
  };
}

/// Resolves [inputs] against the guards: the count cap, per-image byte cap
/// (inline variants), readable sandbox paths, and base64 that decodes.
/// URLs pass through untouched (the provider validates them).
Future<List<ResolvedMediaImage>> resolveMediaImageInputs(
  ExecutionEnv env,
  List<MediaImageInput> inputs,
) async {
  if (inputs.length > maxMediaImageReferences) {
    throw MediaException(
      'too many reference images: ${inputs.length} '
      '(cap $maxMediaImageReferences)',
    );
  }
  final resolved = <ResolvedMediaImage>[];
  for (final input in inputs) {
    switch (input) {
      case MediaImageUrl():
        resolved.add(ResolvedMediaImage.remote(input.url));
      case MediaImageBase64():
        final bytes = _tryBase64Decode(input.base64);
        if (bytes == null) {
          throw MediaException('reference image is not valid base64');
        }
        resolved.add(ResolvedMediaImage.inline(bytes));
      case MediaImagePath():
        final read = await env.readBinaryFile(input.path);
        if (read.isErr) {
          throw MediaException(
            'cannot read reference image at "${input.path}": '
            '${read.errorOrNull}',
          );
        }
        resolved.add(ResolvedMediaImage.inline(read.valueOrNull!));
    }
  }
  return resolved;
}

List<int>? _tryBase64Decode(String value) {
  try {
    return base64Decode(value);
  } on FormatException {
    return null;
  }
}

/// The discovered capabilities of one endpoint's model.
final class EndpointCapabilities {
  const EndpointCapabilities({this.input = const [], this.output = const []});

  /// Input modalities the endpoint accepts (e.g. `text`, `image`, `video`).
  final List<String> input;

  /// Output modalities the endpoint produces (e.g. `image`, `video`).
  final List<String> output;

  /// True when [input] declares `image`.
  bool get acceptsImages => input.contains('image');
}

/// Parses OpenRouter `/api/v1/models` metadata for [modelId]'s
/// architecture: `architecture.input_modalities` / `output_modalities`.
/// Returns null when the model is absent or carries no architecture —
/// capability discovery must degrade to "unknown", never to a guess.
EndpointCapabilities? parseOpenRouterCapabilities(
  Map<String, dynamic> modelsJson,
  String modelId,
) {
  final data = modelsJson['data'];
  if (data is! List) return null;
  for (final entry in data) {
    if (entry is! Map) continue;
    if (entry['id'] != modelId) continue;
    final architecture = entry['architecture'];
    if (architecture is! Map) return null;
    return EndpointCapabilities(
      input: _modalityList(architecture['input_modalities']),
      output: _modalityList(architecture['output_modalities']),
    );
  }
  return null;
}

List<String> _modalityList(Object? value) {
  if (value is! List) return const [];
  return [
    for (final entry in value)
      if (entry is String) entry,
  ];
}

/// True when [baseUrl] points at an OpenRouter host (capability discovery
/// and the OpenRouter dialects key off this, never off model names).
bool isOpenRouterBaseUrl(String baseUrl) {
  final host = Uri.tryParse(baseUrl)?.host.toLowerCase() ?? '';
  return host == 'openrouter.ai' || host.endsWith('.openrouter.ai');
}

/// The OpenRouter model-metadata URL for [baseUrl]'s origin
/// (`{origin}/api/v1/models`).
Uri openRouterModelsUri(String baseUrl) {
  final uri = Uri.parse(baseUrl);
  return Uri(
    scheme: uri.scheme.isEmpty ? 'https' : uri.scheme,
    host: uri.host,
    port: uri.hasPort ? uri.port : null,
    path: '/api/v1/models',
  );
}

/// Resolves the effective input modalities for a media call:
/// [declared] (the slot override's `input:` list) wins; otherwise
/// OpenRouter endpoints are DISCOVERED from the model metadata
/// (`null` when the discovery is unavailable — unknown means "let the
/// provider validate", declared/discovered means "check before the call").
Future<List<String>?> resolveInputModalities({
  required String baseUrl,
  required String apiKey,
  required String modelId,
  List<String> declared = const [],
  required http.Client client,
}) async {
  if (declared.isNotEmpty) return declared;
  if (!isOpenRouterBaseUrl(baseUrl)) return null;
  try {
    final response = await client.get(
      openRouterModelsUri(baseUrl),
      headers: {if (apiKey.isNotEmpty) 'Authorization': 'Bearer $apiKey'},
    );
    if (response.statusCode != 200) return null;
    final decoded = jsonDecode(response.body);
    if (decoded is! Map<String, dynamic>) return null;
    final capabilities = parseOpenRouterCapabilities(decoded, modelId);
    return capabilities?.input;
  } on Object {
    return null;
  }
}

/// The pre-flight capability gate for reference images (gh-1844): throws
/// a [MediaException] naming the slot/model and its declared/discovered
/// modalities when the endpoint is KNOWN not to accept images. Unknown
/// endpoints are the user's explicit configuration — the provider's own
/// error surfaces (documented in `docs/media-models.md`).
void ensureImageInputSupported({
  required String slot,
  required String modelId,
  required List<String>? inputModalities,
}) {
  if (inputModalities == null || inputModalities.contains('image')) return;
  throw MediaException(
    'the $slot endpoint (model "$modelId") does not accept image input '
    '(declared input modalities: ${inputModalities.join(', ')}). Remove '
    'the images argument for a text-only call, or point the slot at a '
    'model with image input.',
  );
}

/// Per-modality media model slots — the schema shared between the Flutter
/// app and the CLI.
///
/// The app persists slot overrides as `media_models.json` (see
/// `flutter_app/lib/services/media_models_store.dart`); the CLI persists
/// them in the `models:` section of `~/.fah/config.yaml` (see
/// [ModelsConfig](models_config.dart)). Both read and write the same slot
/// names and per-slot fields, so those live here exactly once:
///
/// - [mediaModelSlotIds] — the slot names, in declaration order.
/// - [mediaSlotOverrideFields] — the per-slot override fields.
/// - [MediaSlotModelConfig] — one slot override, with strict yaml parsing
///   for the CLI config (the app store keeps its own tolerant JSON form).
library;

import 'dart:convert';

import 'package:yaml/yaml.dart';

import '../exceptions.dart';

/// Every known media slot name, in declaration order.
///
/// Exact app slot names (`MediaSlot.all` in
/// `flutter_app/lib/services/media_models_store.dart` derives from this
/// list): `imageGeneration`, `audioTts`, `musicGeneration`,
/// `videoGeneration`, `vision`, `transcription`.
const mediaModelSlotIds = [
  'imageGeneration',
  'audioTts',
  'musicGeneration',
  'videoGeneration',
  'vision',
  'transcription',
];

/// The fields one media slot override carries (same names in the app's
/// `media_models.json` and the CLI's `models:` yaml section).
///
/// `apiKeyName` is the NAME of an env/secure-store entry holding the API
/// key, never the key itself — key values are never written to config.
/// `useMainConnection` is the explicit per-slot opt-in to serve the slot
/// from the main connection (default false — without an override the slot
/// is UNCONFIGURED, never silently inherited). `input`/`output` declare
/// the endpoint's modalities for capability checks (e.g. reference images
/// need `input: [text, image]`).
const mediaSlotOverrideFields = [
  'providerKind',
  'baseUrl',
  'modelId',
  'apiKeyName',
  'useMainConnection',
  'input',
  'output',
];

/// One media slot override in the CLI's `models:` config section: where ONE
/// media modality is served when the main connection should not handle it.
///
/// Mirrors the app's `MediaSlotOverride` field-for-field; the media tools
/// speak the OpenAI-compatible wire format, so usable overrides carry
/// `providerKind: openai-completions`.
///
/// gh-1844: with `useMainConnection: true` the slot is served by the main
/// connection EXPLICITLY (its baseUrl, model id, and key) — the user says
/// so per slot; nothing is ever inherited implicitly.
final class MediaSlotModelConfig {
  /// Creates a slot override. [providerKind]/[baseUrl]/[modelId] should be
  /// non-empty for a normal override (enforced by [fromYaml] unless
  /// `useMainConnection` is set); all default to empty for the
  /// main-connection opt-in form.
  const MediaSlotModelConfig({
    this.providerKind = '',
    this.baseUrl = '',
    this.modelId = '',
    this.apiKeyName,
    this.useMainConnection = false,
    this.inputModalities = const [],
    this.outputModalities = const [],
  });

  /// Parses one slot entry from yaml, strictly: unknown fields, missing
  /// required strings, and empty values throw [ConfigException] (a bad
  /// `models:` section must surface, never silently vanish). With
  /// `useMainConnection: true` the endpoint fields are not required (the
  /// main connection supplies them); without it they are, exactly as
  /// before gh-1844.
  factory MediaSlotModelConfig.fromYaml(Object? node, {required String slot}) {
    if (node is! YamlMap) {
      throw ConfigException(
        'models.slots.$slot must be a map with fields '
        '${mediaSlotOverrideFields.join(', ')}',
      );
    }
    for (final key in node.keys) {
      if (!mediaSlotOverrideFields.contains(key)) {
        throw ConfigException(
          'unknown field "$key" in models.slots.$slot — expected '
          '${mediaSlotOverrideFields.join(', ')}',
        );
      }
    }
    final useMain = _parseUseMainConnection(node['useMainConnection'], slot);
    String required(String field) {
      final value = node[field];
      if (value is! String || value.trim().isEmpty) {
        throw ConfigException(
          'models.slots.$slot.$field must be a non-empty string',
        );
      }
      return value.trim();
    }

    final apiKeyName = node['apiKeyName'];
    if (apiKeyName != null &&
        (apiKeyName is! String || apiKeyName.trim().isEmpty)) {
      throw ConfigException(
        'models.slots.$slot.apiKeyName must be a non-empty string',
      );
    }
    return MediaSlotModelConfig(
      providerKind: useMain
          ? _optString(node['providerKind'])
          : required('providerKind'),
      baseUrl: useMain ? _optString(node['baseUrl']) : required('baseUrl'),
      modelId: useMain ? _optString(node['modelId']) : required('modelId'),
      apiKeyName: (apiKeyName as String?)?.trim(),
      useMainConnection: useMain,
      inputModalities: _parseModalities(node['input'], slot, 'input'),
      outputModalities: _parseModalities(node['output'], slot, 'output'),
    );
  }

  static String _optString(Object? value) =>
      value is String ? value.trim() : '';

  static bool _parseUseMainConnection(Object? value, String slot) {
    if (value == null) return false;
    if (value is! bool) {
      throw ConfigException(
        'models.slots.$slot.useMainConnection must be a boolean',
      );
    }
    return value;
  }

  static List<String> _parseModalities(
    Object? value,
    String slot,
    String field,
  ) {
    if (value == null) return const [];
    if (value is! YamlList || value.isEmpty) {
      throw ConfigException(
        'models.slots.$slot.$field must be a non-empty list of modality '
        'strings (e.g. [text, image])',
      );
    }
    final result = <String>[];
    for (final entry in value) {
      if (entry is! String || entry.trim().isEmpty) {
        throw ConfigException(
          'models.slots.$slot.$field entries must be non-empty strings',
        );
      }
      result.add(entry.trim());
    }
    return result;
  }

  /// Provider adapter kind (`openai-completions` for usable media
  /// endpoints); empty on the `useMainConnection` opt-in form.
  final String providerKind;

  /// OpenAI-compatible base URL the per-modality path is appended to.
  final String baseUrl;

  /// Model id passed to the endpoint (e.g. `gpt-image-1`, `tts-1`).
  final String modelId;

  /// Name of the env/secure-store entry holding the API key for this
  /// endpoint; null reuses the main connection's key when the override's
  /// baseUrl is on the main connection's host (never across hosts).
  final String? apiKeyName;

  /// Explicit per-slot opt-in (gh-1844): serve this slot from the main
  /// connection. Default false — without an override the slot is
  /// UNCONFIGURED, never silently inherited from the main connection.
  final bool useMainConnection;

  /// Declared input modalities of the endpoint (e.g. `[text, image]`) —
  /// drives capability checks (reference images require `image`). Empty =
  /// undeclared (OpenRouter endpoints may be discovered at call time).
  final List<String> inputModalities;

  /// Declared output modalities of the endpoint (e.g. `[image]`, `[video]`).
  final List<String> outputModalities;

  /// True when this entry is the explicit main-connection opt-in and does
  /// not carry its own endpoint.
  bool get isMainConnectionOptIn => useMainConnection;

  /// Writes the override as yaml lines at [indent] (string values are
  /// JSON-quoted — valid yaml scalars that round-trip any url/model id).
  void writeYaml(StringBuffer buffer, String indent) {
    if (useMainConnection) {
      buffer.write('${indent}useMainConnection: true\n');
      return;
    }
    buffer
      ..write('${indent}providerKind: ${jsonEncode(providerKind)}\n')
      ..write('${indent}baseUrl: ${jsonEncode(baseUrl)}\n')
      ..write('${indent}modelId: ${jsonEncode(modelId)}\n');
    final keyName = apiKeyName;
    if (keyName != null) {
      buffer.write('${indent}apiKeyName: ${jsonEncode(keyName)}\n');
    }
    if (inputModalities.isNotEmpty) {
      buffer.write('${indent}input: ${jsonEncode(inputModalities)}\n');
    }
    if (outputModalities.isNotEmpty) {
      buffer.write('${indent}output: ${jsonEncode(outputModalities)}\n');
    }
  }

  @override
  String toString() =>
      'MediaSlotModelConfig($providerKind, $baseUrl, '
      '$modelId${apiKeyName == null ? '' : ', key: $apiKeyName'})';
}

/// Image generation tool (`generate_image`) for [AgentCli].
///
/// A pure-Dart image-generation client that saves the PNG into the sandbox
/// `generated/` dir. Dialects:
/// - OpenRouter `POST {base}/images` (`input_references` for reference
///   images, `data[].b64_json` + `media_type`) — detected by the
///   `openrouter.ai` host (gh-1844).
/// - OpenAI-compatible `POST {base}/images/generations` (`size`,
///   `data[0].b64_json`/`url`) — the default for every other endpoint.
/// - DIAL `POST {base}/openai/deployments/{model}/chat/completions`.
/// - MiniMax `POST {base}/image_generation` (`aspect_ratio`, `image-01`,
///   `response_format: base64`, `data.image_base64[]`).
///
/// The image bytes never enter the main chat context — the saved path and a
/// base64-staged [ImageContent] are returned. Web-safe.
library;

import 'dart:convert';
import 'dart:math';
import 'dart:typed_data';

import 'package:http/http.dart' as http;

import '../agent/agent_loop.dart' show ToolExecutionResult;
import '../agent/agent_tool.dart';
import '../approval/approval.dart';
import '../env/execution_env.dart';
import '../model_roles/media_model_slots.dart';
import '../model_roles/models_config.dart';
import '../types.dart';
import 'media_reference_images.dart';

final Random _mediaNameRandom = Random.secure();

/// The `generate_image` tool name.
const generateImageToolName = 'generate_image';

/// Directory (relative to the env root) where generated files land.
const generatedMediaDir = 'generated';

/// Failure from a media generation call.
final class MediaException implements Exception {
  /// Creates a [MediaException].
  MediaException(this.message);

  final String message;

  @override
  String toString() => message;
}

/// Resolves a named secret (the slot override's `apiKeyName`) to its value;
/// returns null when the name is unknown.
typedef MediaKeyResolver = Future<String?> Function(String name);

/// The resolved endpoint for a media slot, ready for a request.
final class MediaEndpoint {
  /// Creates an endpoint descriptor.
  const MediaEndpoint({
    required this.baseUrl,
    required this.modelId,
    required this.apiKey,
  });

  /// Base URL the per-modality path is appended to.
  final String baseUrl;

  /// Model id sent in the request body.
  final String modelId;

  /// The resolved API key (empty = no usable credential).
  final String apiKey;
}

/// Resolves the `imageGeneration` slot endpoint for the CLI.
///
/// Mirrors the app's `MediaModelsStore.resolve` (gh-1844): a
/// `models.slots.imageGeneration` override wins; WITHOUT one the slot is
/// UNCONFIGURED (null) — the main connection is never an implicit
/// fallback (sending the chat model id to a media API was the worst
/// case). The main connection serves the slot only through the EXPLICIT
/// per-slot opt-in (`useMainConnection: true`). The slot's `apiKeyName`
/// (or the main key, same-host only) is resolved via [resolveKey].
Future<MediaEndpoint?> resolveImageGenerationEndpoint(
  ModelsConfig? modelsConfig, {
  required String mainBaseUrl,
  required String mainModelId,
  required String mainApiKey,
  MediaKeyResolver? resolveKey,
}) async {
  final override = modelsConfig?.slots['imageGeneration'];
  if (override == null) return null;
  if (override.useMainConnection) {
    if (mainBaseUrl.isEmpty || mainModelId.isEmpty) return null;
    return MediaEndpoint(
      baseUrl: mainBaseUrl,
      modelId: mainModelId,
      apiKey: [REDACTED:Sensitive Value],
    );
  }
  final key = await _resolveSlotKey(
    override,
    mainBaseUrl: mainBaseUrl,
    mainApiKey: mainApiKey,
    resolveKey: resolveKey,
  );
  if (key.isEmpty) {
    final keyName = override.apiKeyName;
    final named = (keyName == null || keyName.isEmpty)
        ? ''
        : ' (named "$keyName")';
    throw MediaException(
      'the imageGeneration slot has no resolvable API key$named '
      '— a slot override never uses the main provider key across hosts; '
      'set models.slots.imageGeneration.apiKeyName to a stored key name '
      '(/key set <name>) or an environment variable',
    );
  }
  return MediaEndpoint(
    baseUrl: override.baseUrl,
    modelId: override.modelId,
    apiKey: [REDACTED:Sensitive Value],
  );
}

bool _isSameHost(String a, String b) {
  final hostA = Uri.tryParse(a)?.host.toLowerCase();
  final hostB = Uri.tryParse(b)?.host.toLowerCase();
  return hostA != null && hostA.isNotEmpty && hostA == hostB;
}

Future<String> _resolveSlotKey(
  MediaSlotModelConfig override, {
  required String mainBaseUrl,
  required String mainApiKey,
  MediaKeyResolver? resolveKey,
}) async {
  final keyName = override.apiKeyName;
  if (keyName != null && keyName.isNotEmpty) {
    return (await resolveKey?.call(keyName)) ?? '';
  }
  if (_isSameHost(override.baseUrl, mainBaseUrl)) {
    return mainApiKey;
  }
  return '';
}

/// One image-generation dialect (its own URL shape, body schema, and
/// response parsing). Adding a provider = one new class + one entry in
/// [imageGenerationDialects]; the dispatcher below never changes.
abstract final class ImageDialect {
  /// Whether this dialect handles [endpoint].
  bool matches(MediaEndpoint endpoint);

  /// Whether this dialect can carry [images] (reference images) — only
  /// the OpenRouter dialect does (gh-1844); every other dialect rejects
  /// them before any network call.
  bool get supportsReferenceImages => false;

  /// Generates an image on the given endpoint.
  Future<({String path, Uint8List bytes, String detail})> generate({
    required ExecutionEnv env,
    required MediaEndpoint endpoint,
    required String prompt,
    String? size,
    String? quality,
    List<ResolvedMediaImage> images = const [],
    required http.Client client,
  });
}

/// Registered image dialects, in precedence order — the MOST SPECIFIC
/// matcher first (OpenRouter before the OpenAI-compatible fallback, which
/// matches everything).
final List<ImageDialect> imageGenerationDialects = [
  DialImageDialect(),
  MiniMaxImageDialect(),
  OpenRouterImageDialect(),
  OpenAiImageDialect(), // default fallback — must stay last
];

/// OpenRouter dedicated Image API (gh-1844):
/// `POST {base}/images` with `{model, prompt, size?, quality?,
/// input_references?}`, answering `{data: [{b64_json, media_type?}],
/// usage?}` — detected by the `openrouter.ai` host. Reference images ride
/// `input_references` (`image_url` entries: http(s) URLs or base64 data
/// URLs), per the official Image API docs. Wire format pinned from
/// https://openrouter.ai/docs/guides/overview/multimodal/image-generation.
final class OpenRouterImageDialect extends ImageDialect {
  @override
  bool matches(MediaEndpoint endpoint) => isOpenRouterBaseUrl(endpoint.baseUrl);

  @override
  bool get supportsReferenceImages => true;

  @override
  Future<({String path, Uint8List bytes, String detail})> generate({
    required ExecutionEnv env,
    required MediaEndpoint endpoint,
    required String prompt,
    String? size,
    String? quality,
    List<ResolvedMediaImage> images = const [],
    required http.Client client,
  }) async {
    final response = await client.post(
      Uri.parse('${_trimSlash(endpoint.baseUrl)}/images'),
      headers: {
        'Content-Type': 'application/json',
        if (endpoint.apiKey.isNotEmpty)
          'Authorization': 'Bearer ${endpoint.apiKey}',
      },
      body: jsonEncode({
        'model': endpoint.modelId,
        'prompt': prompt,
        if (size != null && size.isNotEmpty) 'size': size,
        if (quality != null && quality.isNotEmpty) 'quality': quality,
        if (images.isNotEmpty)
          'input_references': [
            for (final image in images) image.toOpenRouterJson(),
          ],
      }),
    );
    if (response.statusCode != 200) {
      throw MediaException(
        'image generation failed: HTTP ${response.statusCode}: '
        '${response.body}',
      );
    }
    final data = jsonDecode(response.body) as Map<String, dynamic>;
    final first = data['data'] is List && (data['data'] as List).isNotEmpty
        ? (data['data'] as List).first
        : null;
    if (first is! Map<String, dynamic>) {
      throw MediaException('image generation: no image in OpenRouter response');
    }
    final mediaType = first['media_type']?.toString();
    final ext = mediaType != null && mediaType.startsWith('image/')
        ? mediaType.substring('image/'.length)
        : 'png';
    final b64 = first['b64_json'];
    if (b64 is String && b64.isNotEmpty) {
      final bytes = base64Decode(b64);
      final path = await _save(env, 'images', ext, bytes);
      return (path: path, bytes: bytes, detail: 'saved to $path');
    }
    final url = first['url'];
    if (url is String && url.isNotEmpty) {
      final bytes = await _download(url, client);
      final path = await _save(env, 'images', ext, bytes);
      return (path: path, bytes: bytes, detail: 'saved to $path');
    }
    throw MediaException('image generation: no image in OpenRouter response');
  }

  String _trimSlash(String url) =>
      url.endsWith('/') ? url.substring(0, url.length - 1) : url;
}

/// DIAL image generation (`POST {base}/openai/deployments/{model}/chat/completions`,
/// `Api-Key: {key}`, reading `custom_content.attachments[0].url`,
/// downloaded from `{base}/v1/{url}`).
final class DialImageDialect extends ImageDialect {
  @override
  bool matches(MediaEndpoint endpoint) {
    final host = Uri.tryParse(endpoint.baseUrl)?.host.toLowerCase() ?? '';
    return host.contains('ai-proxy') ||
        host.contains('dial') ||
        host.endsWith('.epam.com');
  }

  @override
  Future<({String path, Uint8List bytes, String detail})> generate({
    required ExecutionEnv env,
    required MediaEndpoint endpoint,
    required String prompt,
    String? size,
    String? quality,
    List<ResolvedMediaImage> images = const [],
    required http.Client client,
  }) async {
    final base = endpoint.baseUrl.endsWith('/')
        ? endpoint.baseUrl.substring(0, endpoint.baseUrl.length - 1)
        : endpoint.baseUrl;
    final response = await client.post(
      Uri.parse(
        '$base/openai/deployments/${endpoint.modelId}/chat/completions',
      ),
      headers: {
        'Content-Type': 'application/json',
        if (endpoint.apiKey.isNotEmpty) 'Api-Key': [REDACTED:Sensitive Value],
      },
      body: jsonEncode({
        'messages': [
          {'role': 'user', 'content': prompt},
        ],
      }),
    );
    if (response.statusCode != 200) {
      throw MediaException(
        'image generation failed: HTTP ${response.statusCode}: '
        '${response.body}',
      );
    }
    final data = jsonDecode(response.body) as Map<String, dynamic>;
    final attachment = _extractDialAttachment(data);
    if (attachment == null) {
      throw MediaException('image generation: no image in DIAL response');
    }
    final bytes = await _downloadDialAttachment(
      attachment,
      base: base,
      apiKey: [REDACTED:Sensitive Value],
      client: client,
    );
    final path = await _save(env, 'images', 'png', bytes);
    return (path: path, bytes: bytes, detail: 'saved to $path');
  }

  Map<String, dynamic>? _extractDialAttachment(Map<String, dynamic> data) {
    final choices = data['choices'];
    if (choices is! List || choices.isEmpty) return null;
    final first = choices.first;
    if (first is! Map<String, dynamic>) return null;
    final msg = first['message'];
    if (msg is! Map<String, dynamic>) return null;
    final customContent = msg['custom_content'];
    if (customContent is! Map<String, dynamic>) return null;
    final attachments = customContent['attachments'];
    if (attachments is! List || attachments.isEmpty) return null;
    final att = attachments.first;
    return att is Map<String, dynamic> ? att : null;
  }

  /// Inline base64 image payload (`b64_json`/`data`), `null` when the
  /// attachment carries none.
  Uint8List? _dialInlineImage(Map<String, dynamic> att) {
    final b64 = att['b64_json'] ?? att['data'];
    if (b64 is String && b64.isNotEmpty) {
      return base64Decode(b64);
    }
    return null;
  }

  /// Absolute `http(s)://` URLs pass through; DIAL-relative URLs resolve
  /// against `$base/v1/`.
  String _dialDownloadUrl(String relUrl, String base) {
    if (relUrl.startsWith('http://') || relUrl.startsWith('https://')) {
      return relUrl;
    }
    return '$base/v1/${relUrl.startsWith('/') ? relUrl.substring(1) : relUrl}';
  }

  Future<Uint8List> _downloadDialAttachment(
    Map<String, dynamic> att, {
    required String base,
    required String apiKey,
    required http.Client client,
  }) async {
    final inline = _dialInlineImage(att);
    if (inline != null) {
      return inline;
    }
    final relUrl = att['url'] as String?;
    if (relUrl == null || relUrl.isEmpty) {
      throw MediaException('image generation: no image in DIAL response');
    }
    final imgResp = await client.get(
      Uri.parse(_dialDownloadUrl(relUrl, base)),
      headers: {if (apiKey.isNotEmpty) 'Api-Key': [REDACTED:Sensitive Value]},
    );
    if (imgResp.statusCode != 200) {
      throw MediaException(
        'failed to download image from DIAL: HTTP ${imgResp.statusCode}: '
        '${imgResp.body}',
      );
    }
    return imgResp.bodyBytes;
  }
}

/// OpenAI-compatible image generation (`POST {base}/images/generations`,
/// `size`, `data[0].b64_json`/`url`).
final class OpenAiImageDialect extends ImageDialect {
  @override
  bool matches(MediaEndpoint endpoint) => true; // fallback

  @override
  Future<({String path, Uint8List bytes, String detail})> generate({
    required ExecutionEnv env,
    required MediaEndpoint endpoint,
    required String prompt,
    String? size,
    String? quality,
    List<ResolvedMediaImage> images = const [],
    required http.Client client,
  }) async {
    final response = await client.post(
      Uri.parse('${endpoint.baseUrl}/images/generations'),
      headers: {
        'Content-Type': 'application/json',
        if (endpoint.apiKey.isNotEmpty)
          'Authorization': 'Bearer ${endpoint.apiKey}',
      },
      body: jsonEncode({
        'model': endpoint.modelId,
        'prompt': prompt,
        'size': ?size,
        'quality': ?quality,
      }),
    );
    if (response.statusCode != 200) {
      throw MediaException(
        'image generation failed: HTTP ${response.statusCode}: '
        '${response.body}',
      );
    }
    final data = jsonDecode(response.body) as Map<String, dynamic>;
    final b64 = data['data']?[0]?['b64_json'];
    if (b64 is String) {
      final bytes = base64Decode(b64);
      final path = await _save(env, 'images', 'png', bytes);
      return (path: path, bytes: bytes, detail: 'saved to $path');
    }
    final url = data['data']?[0]?['url'];
    if (url is String) {
      final bytes = await _download(url, client);
      final path = await _save(env, 'images', 'png', bytes);
      return (path: path, bytes: bytes, detail: 'saved to $path');
    }
    throw MediaException('image generation: no image in response');
  }
}

/// MiniMax image generation (`POST {base}/image_generation`,
/// `model: image-01`, `aspect_ratio`, `response_format: base64`).
final class MiniMaxImageDialect extends ImageDialect {
  @override
  bool matches(MediaEndpoint endpoint) => endpoint.baseUrl.contains('minimax');

  /// Maps an OpenAI-style `size` ("1024x1024") to a MiniMax `aspect_ratio`
  /// ("1:1"). Falls back to `1:1` for unknown sizes.
  String _aspectRatio(String? size) {
    if (size == null) return '1:1';
    final parts = size.toLowerCase().split('x');
    if (parts.length == 2) {
      final w = int.tryParse(parts[0]);
      final h = int.tryParse(parts[1]);
      if (w != null && h != null) {
        final gcd = _gcd(w, h);
        return '${w ~/ gcd}:${h ~/ gcd}';
      }
    }
    return '1:1';
  }

  @override
  Future<({String path, Uint8List bytes, String detail})> generate({
    required ExecutionEnv env,
    required MediaEndpoint endpoint,
    required String prompt,
    String? size,
    String? quality,
    List<ResolvedMediaImage> images = const [],
    required http.Client client,
  }) async {
    final base = endpoint.baseUrl.endsWith('/')
        ? endpoint.baseUrl.substring(0, endpoint.baseUrl.length - 1)
        : endpoint.baseUrl;
    final response = await client.post(
      Uri.parse('$base/image_generation'),
      headers: {
        'Content-Type': 'application/json',
        if (endpoint.apiKey.isNotEmpty)
          'Authorization': 'Bearer ${endpoint.apiKey}',
      },
      body: jsonEncode({
        'model': 'image-01',
        'prompt': prompt,
        'aspect_ratio': _aspectRatio(size),
        'response_format': 'base64',
      }),
    );
    if (response.statusCode != 200) {
      throw MediaException(
        'image generation failed: HTTP ${response.statusCode}: '
        '${response.body}',
      );
    }
    final data = jsonDecode(response.body) as Map<String, dynamic>;
    _throwOnMiniMaxError(data);
    final images = data['data']?['image_base64'];
    if (images is List && images.isNotEmpty && images.first is String) {
      final bytes = base64Decode(images.first as String);
      final path = await _save(env, 'images', 'png', bytes);
      return (path: path, bytes: bytes, detail: 'saved to $path');
    }
    throw MediaException('image generation: no image in MiniMax response');
  }

  /// MiniMax reports failures INSIDE HTTP 200 responses as
  /// `{"base_resp":{"status_code":1004,"status_msg":"login fail: ..."}}` —
  /// without this check the dialect reports a misleading
  /// "no image in MiniMax response" instead of the auth/config problem.
  void _throwOnMiniMaxError(Map<String, dynamic> data) {
    final baseResp = data['base_resp'];
    if (baseResp is! Map<String, dynamic>) return;
    final code = baseResp['status_code'];
    if (code is num && code != 0) {
      final msg = baseResp['status_msg'];
      throw MediaException(
        'MiniMax image_generation failed: base_resp $code'
        '${msg is String && msg.isNotEmpty ? ': $msg' : ''} '
        '(MiniMax hides errors inside HTTP 200; the imageGeneration slot '
        'likely needs its own MiniMax key — set '
        'models.slots.imageGeneration.apiKeyName)',
      );
    }
  }
}

int _gcd(int a, int b) {
  var x = a;
  var y = b;
  while (y != 0) {
    final t = x % y;
    x = y;
    y = t;
  }
  return x;
}

/// Generates an image on the `imageGeneration` endpoint and saves the PNG
/// into [generatedMediaDir]. Returns the saved path, bytes, and detail.
///
/// [images] are reference images (gh-1844): they are validated against
/// the endpoint's CAPABILITIES (declared on the slot or discovered from
/// OpenRouter model metadata — never model-name checks) BEFORE the
/// generation call, so an endpoint that does not accept images fails with
/// an actionable error instead of a provider 400. Only the OpenRouter
/// dialect can carry them; other dialects refuse them up front.
///
/// Dispatches to the first dialect in [imageGenerationDialects] whose
/// `matches(endpoint)` returns true.
Future<({String path, Uint8List bytes, String detail})> generateImageBytes({
  required ExecutionEnv env,
  required MediaEndpoint endpoint,
  required String prompt,
  String? size,
  String? quality,
  List<MediaImageInput> images = const [],
  List<String> declaredInputModalities = const [],
  http.Client? httpClient,
}) async {
  final client = httpClient ?? http.Client();
  try {
    final dialect = imageGenerationDialects
        .where((d) => d.matches(endpoint))
        .firstOrNull;
    if (dialect == null) {
      throw MediaException('image generation: no matching dialect');
    }
    final resolvedImages = images.isEmpty
        ? const <ResolvedMediaImage>[]
        : await resolveMediaImageInputs(env, images);
    if (resolvedImages.isNotEmpty) {
      if (!dialect.supportsReferenceImages) {
        throw MediaException(
          'reference images are only supported by the OpenRouter image '
          'dialect — point the imageGeneration slot at an OpenRouter '
          'endpoint (or drop the images argument)',
        );
      }
      ensureImageInputSupported(
        slot: 'imageGeneration',
        modelId: endpoint.modelId,
        inputModalities: await resolveInputModalities(
          baseUrl: endpoint.baseUrl,
          apiKey: [REDACTED:Sensitive Value],
          modelId: endpoint.modelId,
          declared: declaredInputModalities,
          client: client,
        ),
      );
    }
    return await dialect.generate(
      env: env,
      endpoint: endpoint,
      prompt: prompt,
      size: size,
      quality: quality,
      images: resolvedImages,
      client: client,
    );
  } finally {
    client.close();
  }
}

Future<String> _save(
  ExecutionEnv env,
  String prefix,
  String ext,
  Uint8List bytes,
) async {
  final dir = generatedMediaDir;
  final created = await env.createDir(dir, recursive: true);
  if (created.isErr) {
    throw MediaException('failed to create $dir: ${created.errorOrNull}');
  }
  // Milliseconds alone collide when two calls land in the same batch (or
  // two fa processes generate at once) — one would overwrite the other.
  // dart2js: shifts are 32-bit — `1 << 32` == 0, so nextInt(0) would throw
  // on web (issue #1074). Spell the bound literally.
  final unique =
      DateTime.now().microsecondsSinceEpoch.toRadixString(36) +
      _mediaNameRandom.nextInt(0xFFFFFFFF).toRadixString(36);
  final name =
      '${prefix}_${DateTime.now().millisecondsSinceEpoch}_$unique.$ext';
  final rel = '$dir/$name';
  final written = await env.writeBinaryFile(rel, bytes);
  if (written.isErr) {
    throw MediaException('failed to write $rel: ${written.errorOrNull}');
  }
  return rel;
}

Future<Uint8List> _download(String url, http.Client client) async {
  final response = await client.get(Uri.parse(url));
  if (response.statusCode != 200) {
    throw MediaException('failed to download image: ${response.statusCode}');
  }
  return response.bodyBytes;
}

/// Builds the `generate_image` [AgentTool] for the CLI. The endpoint is
/// resolved lazily per call so a `/models set imageGeneration ...` switch is
/// picked up without a restart.
///
/// gh-1844: without a `models.slots.imageGeneration` override (or the
/// explicit `useMainConnection: true` opt-in) the tool fails with an
/// actionable "configure the slot" error — the main connection is never
/// an implicit fallback. The optional `images` argument carries reference
/// images (sandbox paths, http(s) URLs, or base64) for multimodal
/// endpoints.
AgentTool generateImageTool({
  required ExecutionEnv env,
  required ModelsConfig? modelsConfig,
  required String Function() mainBaseUrl,
  required String Function() mainModelId,
  required String Function() mainApiKey,
  MediaKeyResolver? resolveKey,
  http.Client? httpClient,
}) {
  return AgentTool(
    name: generateImageToolName,
    label: generateImageToolName,
    tier: ApprovalTier.write,
    description:
        'Generates an image from a text prompt. Requires the '
        'imageGeneration slot to be configured (models.slots.'
        'imageGeneration in ~/.fah/config.yaml, or useMainConnection: '
        'true to opt into the main connection explicitly). Returns a path '
        'to the saved image file. Arguments: prompt (required), size '
        '(optional, e.g. "1024x1024"), quality (optional), images '
        '(optional, list of reference images: sandbox paths, http(s) URLs, '
        'or base64 — supported by OpenRouter image endpoints that accept '
        'image input).',
    parameters: const {
      'type': 'object',
      'properties': {
        'prompt': {
          'type': 'string',
          'description': 'text prompt describing the image to generate',
        },
        'size': {'type': 'string', 'description': 'image size, e.g. 1024x1024'},
        'quality': {
          'type': 'string',
          'description': 'image quality, e.g. standard or high',
        },
        'images': {
          'type': 'array',
          'items': {'type': 'string'},
          'description':
              'optional reference images (sandbox path, http(s) URL, or '
              'base64) for endpoints that accept image input',
        },
      },
      'required': ['prompt'],
    },
    execute: (arguments, cancelToken, onUpdate) async {
      cancelToken?.throwIfCancelled();
      final prompt = arguments['prompt'] as String? ?? '';
      final size = arguments['size'] as String?;
      final quality = arguments['quality'] as String?;
      if (prompt.trim().isEmpty) {
        throw MediaException('prompt is required');
      }
      final override = modelsConfig?.slots['imageGeneration'];
      final endpoint = await resolveImageGenerationEndpoint(
        modelsConfig,
        mainBaseUrl: mainBaseUrl(),
        mainModelId: mainModelId(),
        mainApiKey: mainApiKey(),
        resolveKey: resolveKey,
      );
      cancelToken?.throwIfCancelled();
      if (endpoint == null) {
        throw MediaException(
          'no endpoint configured for slot imageGeneration; set one in '
          'models.slots.imageGeneration (~/.fah/config.yaml), e.g. via '
          '/models set imageGeneration <model> <baseUrl>. To serve the '
          'slot from the main connection explicitly, set '
          'models.slots.imageGeneration.useMainConnection: true.',
        );
      }
      final imageArgs = arguments['images'];
      final images = <MediaImageInput>[
        if (imageArgs is List)
          for (final entry in imageArgs)
            if (entry != null) parseMediaImageInput(entry.toString()),
      ];
      final file = await generateImageBytes(
        env: env,
        endpoint: endpoint,
        prompt: prompt,
        size: size,
        quality: quality,
        images: images,
        declaredInputModalities: override?.inputModalities ?? const [],
        httpClient: httpClient,
      );
      cancelToken?.throwIfCancelled();
      return ToolExecutionResult(
        content: [
          TextContent(text: 'saved image to ${file.path} (${file.detail})'),
          ImageContent(data: base64Encode(file.bytes), mimeType: 'image/png'),
        ],
      );
    },
  );
}

/// Video generation tool (`generate_video`) for [AgentCli].
///
/// A pure-Dart video-generation client that saves the MP4 into the sandbox
/// `generated/` dir. One dialect is supported:
/// - MiniMax `POST {base}/video_generation` (V2, async, `MiniMax-H3`) —
///   detected by the `minimax` baseUrl marker. The endpoint answers a
///   `task_id`; we poll `GET {base}/query/video_generation?task_id=…`
///   until the task succeeds and the video file URL lands, then download.
///
/// Without a MiniMax endpoint the tool refuses the call with a clear
/// diagnostic — the chat endpoint's `/v1/models` never lists video
/// models, so a slot-less pick falls back to the chat endpoint, which
/// can't generate video. Never silently fall back to the chat model.
library;

import 'dart:async';
import 'dart:convert';
import 'dart:math';
import 'dart:typed_data';

import 'package:http/http.dart' as http;

import '../agent/agent_loop.dart' show ToolExecutionResult, ToolUpdateCallback;
import '../agent/agent_tool.dart';
import '../approval/approval.dart';
import '../cancel_token.dart';
import '../env/execution_env.dart';
import '../model_roles/models_config.dart';
import '../types.dart';
import 'generate_image.dart' show MediaException;
import 'media_reference_images.dart';

final Random _videoNameRandom = Random.secure();

/// The `generate_video` tool name.
const generateVideoToolName = 'generate_video';

/// Directory (relative to the env root) where generated videos land.
const generatedVideoDir = 'generated';

/// Failure from a video generation call.
final class VideoException implements Exception {
  /// Creates a [VideoException].
  VideoException(this.message);

  final String message;

  @override
  String toString() => message;
}

/// Resolves a named secret (the slot override's `apiKeyName`) to its value;
/// returns null when the name is unknown.
typedef VideoKeyResolver = Future<String?> Function(String name);

/// The resolved endpoint for the `videoGeneration` slot, ready for a
/// request.
final class VideoEndpoint {
  /// Creates an endpoint descriptor.
  const VideoEndpoint({
    required this.baseUrl,
    required this.modelId,
    required this.apiKey,
  });

  /// Base URL the per-modality path is appended to.
  final String baseUrl;

  /// Model id sent in the request body (`MiniMax-H3`).
  final String modelId;

  /// The resolved API key (empty = no usable credential).
  final String apiKey;
}

/// Resolves the `videoGeneration` slot endpoint for the CLI.
///
/// Mirrors the app's `MediaModelsStore.resolve` (gh-1844): a
/// `models.slots.videoGeneration` override wins; without one the slot
/// is UNCONFIGURED (null — the main connection is not a fallback: its
/// `/v1/models` never lists video models and the chat endpoint can't
/// generate video). The main connection serves the slot only through
/// the EXPLICIT per-slot opt-in (`useMainConnection: true`).
Future<VideoEndpoint?> resolveVideoGenerationEndpoint(
  ModelsConfig? modelsConfig, {
  String mainBaseUrl = '',
  String mainModelId = '',
  String mainApiKey = '',
  VideoKeyResolver? resolveKey,
}) async {
  final override = modelsConfig?.slots['videoGeneration'];
  if (override == null) return null;
  if (override.useMainConnection) {
    if (mainBaseUrl.isEmpty || mainModelId.isEmpty) return null;
    return VideoEndpoint(
      baseUrl: mainBaseUrl,
      modelId: mainModelId,
      apiKey: [REDACTED:Sensitive Value],
    );
  }
  final key = override.apiKeyName == null
      ? ''
      : (await resolveKey?.call(override.apiKeyName!)) ?? '';
  return VideoEndpoint(
    baseUrl: override.baseUrl,
    modelId: override.modelId,
    apiKey: [REDACTED:Sensitive Value],
  );
}

/// One video-generation dialect (its own URL shape, body schema, and
/// response handling). Adding a provider = one new class + one entry in
/// [videoGenerationDialects]; the dispatcher below never changes.
abstract final class VideoDialect {
  /// Whether this dialect handles [endpoint].
  bool matches(VideoEndpoint endpoint);

  /// Whether this dialect can carry [images] (reference images) — only
  /// the OpenRouter dialect does (gh-1844); every other dialect rejects
  /// them before any network call.
  bool get supportsReferenceImages => false;

  /// Generates a video on the given endpoint. The implementation
  /// handles any async polling the provider requires and returns the
  /// downloaded MP4 bytes plus the saved path.
  Future<({String path, Uint8List bytes, String detail})> generate({
    required ExecutionEnv env,
    required VideoEndpoint endpoint,
    required String prompt,
    String? size,
    String? quality,
    List<ResolvedMediaImage> images = const [],
    required http.Client client,
    Future<void> Function()? onPollProgress,
  });
}

/// Registered video dialects, in precedence order — the MOST SPECIFIC
/// matcher first: both MiniMax dialects share the `minimax` baseUrl
/// marker, so the H3 dialect would swallow Hailuo endpoints if listed
/// first.
final List<VideoDialect> videoGenerationDialects = [
  HailuoVideoDialect(), // Hailuo 2.3 async task (V1 endpoint)
  MiniMaxVideoDialect(), // MiniMax H3 async task (V2)
  OpenRouterVideoDialect(), // OpenRouter /videos async job
];

/// MiniMax video generation (`POST {base}/video_generation`, async,
/// model `MiniMax-H3`). The endpoint returns a `task_id`; we poll
/// `GET {base}/query/video_generation?task_id=…` until it succeeds,
/// then download the returned `file_url`.
final class MiniMaxVideoDialect extends VideoDialect {
  @override
  bool matches(VideoEndpoint endpoint) => endpoint.baseUrl.contains('minimax');

  /// Maps an OpenAI-style `size` ("1920x1080") to a MiniMax `resolution`
  /// ("2K") and `ratio` ("16:9"). Falls back to 2K 16:9 for unknown sizes.
  /// Public for tests.
  ({String resolution, String ratio}) sizeFor(String? size) {
    if (size == null) return (resolution: '2K', ratio: '16:9');
    final parts = size.toLowerCase().split('x');
    if (parts.length == 2) {
      final w = int.tryParse(parts[0]);
      final h = int.tryParse(parts[1]);
      if (w != null && h != null && w > 0 && h > 0) {
        final resolution = w >= 1920 ? '2K' : '1080P';
        final gcd = _gcd(w, h);
        return (resolution: resolution, ratio: '${w ~/ gcd}:${h ~/ gcd}');
      }
    }
    return (resolution: '2K', ratio: '16:9');
  }

  @override
  Future<({String path, Uint8List bytes, String detail})> generate({
    required ExecutionEnv env,
    required VideoEndpoint endpoint,
    required String prompt,
    String? size,
    String? quality,
    List<ResolvedMediaImage> images = const [],
    required http.Client client,
    Future<void> Function()? onPollProgress,
  }) async {
    final base = _trimSlash(endpoint.baseUrl);
    final (resolution: resolution, ratio: ratio) = sizeFor(size);
    final headers = _minimaxHeaders(endpoint);
    final taskId = await _createTask(
      client,
      base,
      headers,
      endpoint.modelId,
      prompt,
      resolution,
      ratio,
    );
    final fileUrl = await _pollForFileUrl(
      client,
      base,
      headers,
      taskId,
      onPollProgress,
    );
    final bytes = await _downloadVideo(client, fileUrl);
    final path = await _save(env, 'videos', 'mp4', bytes);
    return (path: path, bytes: bytes, detail: 'saved to $path');
  }

  String _trimSlash(String url) =>
      url.endsWith('/') ? url.substring(0, url.length - 1) : url;

  Map<String, String> _minimaxHeaders(VideoEndpoint endpoint) => {
    'Content-Type': 'application/json',
    if (endpoint.apiKey.isNotEmpty)
      'Authorization': 'Bearer ${endpoint.apiKey}',
  };

  Future<String> _createTask(
    http.Client client,
    String base,
    Map<String, String> headers,
    String model,
    String prompt,
    String resolution,
    String ratio,
  ) async {
    final create = await client.post(
      Uri.parse('$base/v2/video_generation'),
      headers: headers,
      body: jsonEncode({
        'model': model,
        'content': [
          {'type': 'text', 'text': prompt},
        ],
        'resolution': resolution,
        'ratio': ratio,
        'duration': 5,
      }),
    );
    if (create.statusCode != 200) {
      throw VideoException(
        'video generation failed: HTTP ${create.statusCode}: ${create.body}',
      );
    }
    final created = jsonDecode(create.body) as Map<String, dynamic>;
    final taskId = created['task_id'] as String?;
    if (taskId == null) {
      throw VideoException(
        'video generation: MiniMax response missing task_id: ${create.body}',
      );
    }
    return taskId;
  }

  Future<String> _pollForFileUrl(
    http.Client client,
    String base,
    Map<String, String> headers,
    String taskId,
    Future<void> Function()? onProgress,
  ) async {
    const maxPolls = 20;
    for (var i = 0; i < maxPolls; i++) {
      final data = await _pollOnce(client, base, headers, taskId);
      final status = data['status'] as String?;
      if (status == 'Success') return _fileUrlFrom(data, taskId);
      _throwIfFailed(data, status, taskId);
      _throwIfCancelled(status, taskId);
      await onProgress?.call();
      // Back off linearly: 3s, 4s, 5s, …, capped at 10s. 20 polls
      // ≈ 2 minutes worst case.
      final delaySeconds = (3 + i).clamp(3, 10);
      await Future<void>.delayed(Duration(seconds: delaySeconds));
    }
    throw VideoException(
      'video task $taskId did not finish within the polling window',
    );
  }

  String _fileUrlFrom(Map<String, dynamic> data, String taskId) {
    final fileUrl = data['file_url'] as String?;
    if (fileUrl == null) {
      throw VideoException(
        'video generation: MiniMax task $taskId succeeded without '
        'file_url: ${jsonEncode(data)}',
      );
    }
    return fileUrl;
  }

  void _throwIfFailed(
    Map<String, dynamic> data,
    String? status,
    String taskId,
  ) {
    if (status == 'Failed') {
      throw VideoException('video task $taskId failed: ${jsonEncode(data)}');
    }
  }

  void _throwIfCancelled(String? status, String taskId) {
    if (status == 'Cancelled') {
      throw VideoException('video task $taskId was cancelled');
    }
  }

  Future<Map<String, dynamic>> _pollOnce(
    http.Client client,
    String base,
    Map<String, String> headers,
    String taskId,
  ) async {
    final response = await client.get(
      Uri.parse('$base/v2/query/video_generation?task_id=$taskId'),
      headers: headers,
    );
    if (response.statusCode != 200) {
      throw VideoException(
        'video task query failed: HTTP ${response.statusCode}: '
        '${response.body}',
      );
    }
    return jsonDecode(response.body) as Map<String, dynamic>;
  }

  Future<Uint8List> _downloadVideo(http.Client client, String fileUrl) async {
    final video = await client.get(Uri.parse(fileUrl));
    if (video.statusCode != 200) {
      throw VideoException(
        'video download failed: HTTP ${video.statusCode} for $fileUrl',
      );
    }
    return video.bodyBytes;
  }
}

/// Hailuo 2.3 video generation (`POST {base}/v1/video_generation`, async,
/// model `MiniMax-Hailuo-2.3`). The endpoint returns a `task_id`; we poll
/// `GET {base}/v1/query/video_generation?task_id=…` until it succeeds,
/// then download the returned `file_url`.
final class HailuoVideoDialect extends VideoDialect {
  @override
  bool matches(VideoEndpoint endpoint) =>
      endpoint.baseUrl.contains('minimax') &&
      endpoint.modelId.contains('Hailuo');

  /// Maps an OpenAI-style `size` ("1920x1080") to a Hailuo `resolution`
  /// ("1080P") and `duration` (6s). Falls back to 1080P for unknown sizes.
  /// Public for tests.
  ({String resolution, int duration}) sizeFor(String? size) {
    if (size == null) return (resolution: '1080P', duration: 6);
    final parts = size.toLowerCase().split('x');
    if (parts.length == 2) {
      final w = int.tryParse(parts[0]);
      final h = int.tryParse(parts[1]);
      if (w != null && h != null && w > 0 && h > 0) {
        final resolution = w >= 1920 ? '1080P' : '768P';
        return (resolution: resolution, duration: 6);
      }
    }
    return (resolution: '1080P', duration: 6);
  }

  @override
  Future<({String path, Uint8List bytes, String detail})> generate({
    required ExecutionEnv env,
    required VideoEndpoint endpoint,
    required String prompt,
    String? size,
    String? quality,
    List<ResolvedMediaImage> images = const [],
    required http.Client client,
    Future<void> Function()? onPollProgress,
  }) async {
    final base = _trimSlash(endpoint.baseUrl);
    final (resolution: resolution, duration: duration) = sizeFor(size);
    final headers = _hailuoHeaders(endpoint);
    final taskId = await _createTask(
      client,
      base,
      headers,
      endpoint.modelId,
      prompt,
      resolution,
      duration,
    );
    final fileUrl = await _pollForFileUrl(
      client,
      base,
      headers,
      taskId,
      onPollProgress,
    );
    final bytes = await _downloadVideo(client, fileUrl);
    final path = await _save(env, 'videos', 'mp4', bytes);
    return (path: path, bytes: bytes, detail: 'saved to $path');
  }

  String _trimSlash(String url) =>
      url.endsWith('/') ? url.substring(0, url.length - 1) : url;

  Map<String, String> _hailuoHeaders(VideoEndpoint endpoint) => {
    'Content-Type': 'application/json',
    if (endpoint.apiKey.isNotEmpty)
      'Authorization': 'Bearer ${endpoint.apiKey}',
  };

  Future<String> _createTask(
    http.Client client,
    String base,
    Map<String, String> headers,
    String model,
    String prompt,
    String resolution,
    int duration,
  ) async {
    final create = await client.post(
      Uri.parse('$base/v1/video_generation'),
      headers: headers,
      body: jsonEncode({
        'model': model,
        'prompt': prompt,
        'resolution': resolution,
        'duration': duration,
        'prompt_optimizer': true,
      }),
    );
    if (create.statusCode != 200) {
      throw VideoException(
        'video generation failed: HTTP ${create.statusCode}: ${create.body}',
      );
    }
    final created = jsonDecode(create.body) as Map<String, dynamic>;
    final taskId = created['task_id'] as String?;
    if (taskId == null) {
      throw VideoException(
        'video generation: Hailuo response missing task_id: ${create.body}',
      );
    }
    return taskId;
  }

  Future<String> _pollForFileUrl(
    http.Client client,
    String base,
    Map<String, String> headers,
    String taskId,
    Future<void> Function()? onProgress,
  ) async {
    const maxPolls = 20;
    for (var i = 0; i < maxPolls; i++) {
      final data = await _pollOnce(client, base, headers, taskId);
      final status = data['status'] as String?;
      if (status == 'Success') {
        final fileId = data['file_id'] as String?;
        if (fileId == null) {
          throw VideoException(
            'video generation: Hailuo task $taskId succeeded without '
            'file_id: ${jsonEncode(data)}',
          );
        }
        return _downloadUrlFrom(client, base, headers, fileId);
      }
      _throwIfFailed(data, status, taskId);
      await onProgress?.call();
      final delaySeconds = (3 + i).clamp(3, 10);
      await Future<void>.delayed(Duration(seconds: delaySeconds));
    }
    throw VideoException(
      'video task $taskId did not finish within the polling window',
    );
  }

  Future<String> _downloadUrlFrom(
    http.Client client,
    String base,
    Map<String, String> headers,
    String fileId,
  ) async {
    final retrieve = await client.get(
      Uri.parse('$base/v1/files/retrieve?file_id=$fileId'),
      headers: headers,
    );
    if (retrieve.statusCode != 200) {
      throw VideoException(
        'video file retrieve failed: HTTP ${retrieve.statusCode}: '
        '${retrieve.body}',
      );
    }
    final body = jsonDecode(retrieve.body) as Map<String, dynamic>;
    final file = body['file'] as Map<String, dynamic>?;
    final url = file?['download_url'] as String?;
    if (url == null) {
      throw VideoException(
        'video file retrieve: missing download_url for file_id=$fileId: '
        '${retrieve.body}',
      );
    }
    return url;
  }

  void _throwIfFailed(
    Map<String, dynamic> data,
    String? status,
    String taskId,
  ) {
    if (status == 'Fail') {
      throw VideoException('video task $taskId failed: ${jsonEncode(data)}');
    }
  }

  Future<Map<String, dynamic>> _pollOnce(
    http.Client client,
    String base,
    Map<String, String> headers,
    String taskId,
  ) async {
    final response = await client.get(
      Uri.parse('$base/v1/query/video_generation?task_id=$taskId'),
      headers: headers,
    );
    if (response.statusCode != 200) {
      throw VideoException(
        'video task query failed: HTTP ${response.statusCode}: '
        '${response.body}',
      );
    }
    return jsonDecode(response.body) as Map<String, dynamic>;
  }

  Future<Uint8List> _downloadVideo(http.Client client, String fileUrl) async {
    final video = await client.get(Uri.parse(fileUrl));
    if (video.statusCode != 200) {
      throw VideoException(
        'video download failed: HTTP ${video.statusCode} for $fileUrl',
      );
    }
    return video.bodyBytes;
  }
}

/// OpenRouter video generation (gh-1844): the dedicated asynchronous
/// `POST {base}/videos` contract — submit answers 202 with
/// `{id, polling_url, status}`, the job is polled at the polling URL
/// until `completed`, and the mp4 downloads from `unsigned_urls[0]`
/// (authenticated, same origin). Reference images ride
/// `input_references` (`image_url` entries). Detected by the
/// `openrouter.ai` host — never by model names. Wire format pinned from
/// https://openrouter.ai/docs/guides/overview/multimodal/video-generation.
final class OpenRouterVideoDialect extends VideoDialect {
  @override
  bool matches(VideoEndpoint endpoint) => isOpenRouterBaseUrl(endpoint.baseUrl);

  @override
  bool get supportsReferenceImages => true;

  /// Poll budget: 20 polls with a linear 3→10 s backoff, matching the
  /// MiniMax dialects' worst case (~2 minutes).
  static const int maxPolls = 20;

  @override
  Future<({String path, Uint8List bytes, String detail})> generate({
    required ExecutionEnv env,
    required VideoEndpoint endpoint,
    required String prompt,
    String? size,
    String? quality,
    List<ResolvedMediaImage> images = const [],
    required http.Client client,
    Future<void> Function()? onPollProgress,
  }) async {
    final base = _trimSlash(endpoint.baseUrl);
    final headers = _openRouterHeaders(endpoint);
    final created = await _submit(
      client,
      base,
      headers,
      endpoint.modelId,
      prompt,
      size,
      images,
    );
    final jobId = created.jobId;
    final pollUrl = created.pollingUrl ?? '$base/videos/$jobId';
    final bytes = await _pollAndDownload(
      client,
      headers,
      pollUrl,
      jobId,
      onPollProgress,
    );
    final path = await _save(env, 'videos', 'mp4', bytes);
    return (path: path, bytes: bytes, detail: 'saved to $path');
  }

  String _trimSlash(String url) =>
      url.endsWith('/') ? url.substring(0, url.length - 1) : url;

  Map<String, String> _openRouterHeaders(VideoEndpoint endpoint) => {
    'Content-Type': 'application/json',
    if (endpoint.apiKey.isNotEmpty) 'Authorization': 'Bearer $endpoint.apiKey',
  };

  Future<({String jobId, String? pollingUrl})> _submit(
    http.Client client,
    String base,
    Map<String, String> headers,
    String model,
    String prompt,
    String? size,
    List<ResolvedMediaImage> images,
  ) async {
    final create = await client.post(
      Uri.parse('$base/videos'),
      headers: headers,
      body: jsonEncode({
        'model': model,
        'prompt': prompt,
        if (size != null && size.isNotEmpty) 'size': size,
        if (images.isNotEmpty)
          'input_references': [
            for (final image in images) image.toOpenRouterJson(),
          ],
      }),
    );
    if (create.statusCode != 200 && create.statusCode != 202) {
      throw VideoException(
        'video generation failed: HTTP ${create.statusCode}: ${create.body}',
      );
    }
    final body = jsonDecode(create.body);
    if (body is! Map<String, dynamic>) {
      throw VideoException(
        'video generation: unexpected OpenRouter submit response',
      );
    }
    final jobId = body['id']?.toString();
    if (jobId == null || jobId.isEmpty) {
      throw VideoException(
        'video generation: OpenRouter response missing job id: ${create.body}',
      );
    }
    final pollingUrl = body['polling_url']?.toString();
    return (
      jobId: jobId,
      pollingUrl: pollingUrl != null && pollingUrl.isNotEmpty
          ? pollingUrl
          : null,
    );
  }

  Future<Uint8List> _pollAndDownload(
    http.Client client,
    Map<String, String> headers,
    String pollUrl,
    String jobId,
    Future<void> Function()? onProgress,
  ) async {
    for (var i = 0; i < maxPolls; i++) {
      final job = await _pollOnce(client, headers, pollUrl, jobId);
      final status = job['status']?.toString() ?? '';
      if (status == 'completed' || status == 'succeeded') {
        return _downloadCompleted(client, headers, job, jobId, pollUrl);
      }
      if (status == 'failed' || status == 'cancelled' || status == 'expired') {
        final error = job['error'];
        throw VideoException(
          'video generation job $status${error == null ? '' : ': $error'}.',
        );
      }
      await onProgress?.call();
      final delaySeconds = (3 + i).clamp(3, 10);
      await Future<void>.delayed(Duration(seconds: delaySeconds));
    }
    throw VideoException(
      'video job $jobId did not finish within the polling window',
    );
  }

  Future<Map<String, dynamic>> _pollOnce(
    http.Client client,
    Map<String, String> headers,
    String pollUrl,
    String jobId,
  ) async {
    final response = await client.get(Uri.parse(pollUrl), headers: headers);
    if (response.statusCode != 200) {
      throw VideoException(
        'video status poll failed: HTTP ${response.statusCode}: '
        '${response.body}',
      );
    }
    final decoded = jsonDecode(response.body);
    if (decoded is! Map<String, dynamic>) {
      throw VideoException('video status poll: unexpected OpenRouter response');
    }
    return decoded;
  }

  /// The mp4 bytes of a completed job: `unsigned_urls[0]` (same-origin,
  /// authenticated) or `url`, else the job's content endpoint derived
  /// from [pollUrl]'s base.
  Future<Uint8List> _downloadCompleted(
    http.Client client,
    Map<String, String> headers,
    Map<String, dynamic> job,
    String jobId,
    String pollUrl,
  ) async {
    String? url;
    final unsigned = job['unsigned_urls'];
    if (unsigned is List && unsigned.isNotEmpty) {
      url = unsigned.first?.toString();
    }
    url ??= job['url']?.toString();
    final uri = Uri.parse(
      url != null && url.isNotEmpty ? url : '${_trimSlash(pollUrl)}/content',
    );
    // OpenRouter fills unsigned_urls with same-origin content endpoints
    // that REQUIRE the API key; send it whenever the URL is not absolute
    // or lives on the polling host.
    final sendAuth = uri.host.isEmpty || uri.host == Uri.parse(pollUrl).host;
    final response = await client.get(uri, headers: sendAuth ? headers : null);
    if (response.statusCode != 200) {
      throw VideoException(
        'video download failed: HTTP ${response.statusCode} for $uri',
      );
    }
    return response.bodyBytes;
  }
}

int _gcd(int a, int b) {
  var x = a;
  var y = b;
  while (y != 0) {
    final t = x % y;
    x = y;
    y = t;
  }
  return x;
}

Future<String> _save(
  ExecutionEnv env,
  String prefix,
  String ext,
  Uint8List bytes,
) async {
  final dir = generatedVideoDir;
  final created = await env.createDir(dir, recursive: true);
  if (created.isErr) {
    throw VideoException('failed to create $dir: ${created.errorOrNull}');
  }
  // dart2js: shifts are 32-bit — `1 << 32` == 0, so nextInt(0) would throw
  // on web (issue #1074). Spell the bound literally.
  final unique =
      DateTime.now().microsecondsSinceEpoch.toRadixString(36) +
      _videoNameRandom.nextInt(0xFFFFFFFF).toRadixString(36);
  final name =
      '${prefix}_${DateTime.now().millisecondsSinceEpoch}_$unique.$ext';
  final rel = '$dir/$name';
  final written = await env.writeBinaryFile(rel, bytes);
  if (written.isErr) {
    throw VideoException('failed to write $rel: ${written.errorOrNull}');
  }
  return rel;
}

/// Generates a video on the `videoGeneration` endpoint and saves the MP4
/// into [generatedVideoDir].
///
/// [images] are reference images (gh-1844), validated against the
/// endpoint's CAPABILITIES (declared on the slot or discovered from
/// OpenRouter model metadata) BEFORE the submit call. Only the
/// OpenRouter dialect can carry them.
///
/// Dispatches to the first dialect in [videoGenerationDialects] whose
/// `matches(endpoint)` returns true.
Future<({String path, Uint8List bytes, String detail})> generateVideoBytes({
  required ExecutionEnv env,
  required VideoEndpoint endpoint,
  required String prompt,
  String? size,
  String? quality,
  List<MediaImageInput> images = const [],
  List<String> declaredInputModalities = const [],
  http.Client? httpClient,
  Future<void> Function()? onPollProgress,
}) async {
  final client = httpClient ?? http.Client();
  try {
    final dialect = videoGenerationDialects
        .where((d) => d.matches(endpoint))
        .firstOrNull;
    if (dialect == null) {
      throw VideoException('video generation: no matching dialect');
    }
    final resolvedImages = images.isEmpty
        ? const <ResolvedMediaImage>[]
        : await resolveMediaImageInputs(env, images);
    if (resolvedImages.isNotEmpty) {
      if (!dialect.supportsReferenceImages) {
        throw VideoException(
          'reference images are only supported by the OpenRouter video '
          'dialect — point the videoGeneration slot at an OpenRouter '
          'endpoint (or drop the images argument)',
        );
      }
      try {
        ensureImageInputSupported(
          slot: 'videoGeneration',
          modelId: endpoint.modelId,
          inputModalities: await resolveInputModalities(
            baseUrl: endpoint.baseUrl,
            apiKey: [REDACTED:Sensitive Value],
            modelId: endpoint.modelId,
            declared: declaredInputModalities,
            client: client,
          ),
        );
      } on MediaException catch (e) {
        throw VideoException(e.toString());
      }
    }
    return await dialect.generate(
      env: env,
      endpoint: endpoint,
      prompt: prompt,
      size: size,
      quality: quality,
      images: resolvedImages,
      client: client,
      onPollProgress: onPollProgress,
    );
  } finally {
    client.close();
  }
}

/// Builds the `generate_video` [AgentTool] for the CLI. The endpoint is
/// resolved lazily per call so a `/models set videoGeneration …` switch
/// is picked up without a restart.
AgentTool generateVideoTool({
  required ExecutionEnv env,
  required ModelsConfig? modelsConfig,
  required String Function() mainBaseUrl,
  required String Function() mainModelId,
  required String Function() mainApiKey,
  VideoKeyResolver? resolveKey,
  http.Client? httpClient,
}) {
  return AgentTool(
    name: generateVideoToolName,
    label: generateVideoToolName,
    tier: ApprovalTier.write,
    description:
        'Generates a video from a text prompt. Requires the '
        'videoGeneration slot to be configured (models.slots.'
        'videoGeneration in ~/.fah/config.yaml, or useMainConnection: '
        'true to opt into the main connection explicitly). Returns a path '
        'to the saved MP4 file. Arguments: prompt (required), size '
        '(optional, e.g. "1920x1080"), quality (optional), images '
        '(optional, list of reference images: sandbox paths, http(s) URLs, '
        'or base64 — supported by OpenRouter video endpoints that accept '
        'image input).',
    parameters: const {
      'type': 'object',
      'properties': {
        'prompt': {
          'type': 'string',
          'description': 'text prompt describing the video to generate',
        },
        'size': {'type': 'string', 'description': 'video size, e.g. 1920x1080'},
        'quality': {
          'type': 'string',
          'description': 'video quality, e.g. standard or high',
        },
        'images': {
          'type': 'array',
          'items': {'type': 'string'},
          'description':
              'optional reference images (sandbox path, http(s) URL, or '
              'base64) for endpoints that accept image input',
        },
      },
      'required': ['prompt'],
    },
    execute: (arguments, cancelToken, onUpdate) => _runVideoGeneration(
      arguments: arguments,
      cancelToken: cancelToken,
      onUpdate: onUpdate,
      env: env,
      modelsConfig: modelsConfig,
      mainBaseUrl: mainBaseUrl(),
      mainModelId: mainModelId(),
      mainApiKey: mainApiKey(),
      resolveKey: resolveKey,
      httpClient: httpClient,
    ),
  );
}

/// The `generate_video` execute body: validate the prompt, resolve the
/// slot endpoint lazily per call (a `/models set videoGeneration …`
/// switch is picked up without a restart), then delegate to the matching
/// dialect.
Future<ToolExecutionResult> _runVideoGeneration({
  required Map<String, dynamic> arguments,
  CancelToken? cancelToken,
  ToolUpdateCallback? onUpdate,
  required ExecutionEnv env,
  required ModelsConfig? modelsConfig,
  required String mainBaseUrl,
  required String mainModelId,
  required String mainApiKey,
  VideoKeyResolver? resolveKey,
  http.Client? httpClient,
}) async {
  cancelToken?.throwIfCancelled();
  final prompt = arguments['prompt'] as String? ?? '';
  if (prompt.trim().isEmpty) {
    throw VideoException('prompt is required');
  }
  final endpoint = await _videoEndpointOrThrow(
    modelsConfig,
    resolveKey,
    mainBaseUrl: mainBaseUrl,
    mainModelId: mainModelId,
    mainApiKey: mainApiKey,
  );
  cancelToken?.throwIfCancelled();
  final imageArgs = arguments['images'];
  final images = <MediaImageInput>[
    if (imageArgs is List)
      for (final entry in imageArgs)
        if (entry != null) parseMediaImageInput(entry.toString()),
  ];
  final file = await generateVideoBytes(
    env: env,
    endpoint: endpoint,
    prompt: prompt,
    size: arguments['size'] as String?,
    quality: arguments['quality'] as String?,
    images: images,
    declaredInputModalities:
        modelsConfig?.slots['videoGeneration']?.inputModalities ?? const [],
    httpClient: httpClient,
    onPollProgress: () async {
      // Surface progress to the UI — the polling can take up to
      // ~2 minutes for MiniMax, without a heartbeat the user sees
      // nothing.
      onUpdate?.call(
        ToolExecutionResult(
          content: [TextContent(text: 'video generation: polling task...')],
        ),
      );
    },
  );
  cancelToken?.throwIfCancelled();
  return ToolExecutionResult(
    content: [
      TextContent(text: 'saved video to ${file.path} (${file.detail})'),
    ],
  );
}

/// Resolves the `videoGeneration` slot or throws the named
/// [VideoException] the model can act on.
Future<VideoEndpoint> _videoEndpointOrThrow(
  ModelsConfig? modelsConfig,
  VideoKeyResolver? resolveKey, {
  String mainBaseUrl = '',
  String mainModelId = '',
  String mainApiKey = '',
}) async {
  final endpoint = await resolveVideoGenerationEndpoint(
    modelsConfig,
    mainBaseUrl: mainBaseUrl,
    mainModelId: mainModelId,
    mainApiKey: mainApiKey,
    resolveKey: resolveKey,
  );
  if (endpoint == null) {
    throw VideoException(
      'no endpoint configured for slot videoGeneration; set one in '
      'models.slots.videoGeneration (~/.fah/config.yaml), e.g. via '
      '/models set videoGeneration <model> <baseUrl>. To serve the slot '
      'from the main connection explicitly, set '
      'models.slots.videoGeneration.useMainConnection: true.',
    );
  }
  return endpoint;
}

/// The Decisions API subsystem (gh-1844): OpenRouter's structured
/// decision models (e.g. `inception/mercury-decide:free`,
/// `typesafe/jev-*`).
///
/// A decision model answers TYPED questions about a `state` with
/// CALIBRATED PROBABILITIES instead of free text. The API is NOT
/// OpenAI-chat-compatible — it is served at `{baseUrl}/systemone`
/// (OpenRouter's System One / Decisions API), so this is its own
/// adapter, not a chat dialect flag. There is NO streaming: one request,
/// one JSON response (the non-streaming mapping is deliberate and
/// documented; `decide` never invents a stream where the API has none).
///
/// Provider-adapter discipline:
/// - NO thrown provider errors: every failure — HTTP non-2xx, malformed
///   JSON, local validation — comes back as a structured
///   [DecisionResult.failure] the caller surfaces as-is;
/// - usage accounting when present: [DecisionUsage] parses the
///   response's `usage` block (input/output tokens + cost);
/// - redaction-compatible: the API key rides the `Authorization` header
///   only and never appears in results or error messages.
///
/// Pure Dart: no `dart:io`, fake-HTTP-testable via `http.Client`.
library;

import 'dart:convert';

import 'package:http/http.dart' as http;

/// One typed question about the [state]. The wire discriminator is
/// [type]: `bool` (yes/no probability), `choice` (pick from a keyed
/// criteria map), `score` (position on an ordered criteria list).
sealed class DecisionQuestion {
  const DecisionQuestion();

  /// The wire `type` discriminator.
  String get type;

  /// What the model is asked to decide (free-form instructions).
  Object? get instructions;

  /// The question's `criteria` block (shape depends on [type]).
  Object? get criteria;

  /// The wire form: `{type, instructions, criteria?}`.
  Map<String, dynamic> toJson() => {
    'type': type,
    if (instructions != null) 'instructions': instructions,
    if (criteria != null) 'criteria': criteria,
  };
}

/// A yes/no question answered with a calibrated probability (`bool`).
final class DecisionBoolQuestion extends DecisionQuestion {
  /// Creates a yes/no question; [criteriaTrue]/[criteriaFalse] sharpen
  /// the calibration by describing each branch.
  const DecisionBoolQuestion({
    required this.instructions,
    this.criteriaTrue,
    this.criteriaFalse,
  });

  @override
  String get type => 'bool';

  @override
  final Object? instructions;

  /// Guidance for the `true` branch.
  final Object? criteriaTrue;

  /// Guidance for the `false` branch.
  final Object? criteriaFalse;

  @override
  Object? get criteria => {
    if (criteriaTrue != null) 'true': criteriaTrue,
    if (criteriaFalse != null) 'false': criteriaFalse,
  };
}

/// A pick-one-from-a-fixed-list question (`choice`): the criteria map's
/// KEYS are the allowed answers, its values describe each option.
final class DecisionChoiceQuestion extends DecisionQuestion {
  /// Creates a choice question; [criteria] must be non-empty.
  const DecisionChoiceQuestion({
    required this.instructions,
    required this.criteria,
  });

  @override
  String get type => 'choice';

  @override
  final Object? instructions;

  /// The allowed answers keyed by option id (e.g. `{payments: "..."}`).
  @override
  final Map<String, Object?> criteria;
}

/// A position-on-a-scale question (`score`): the criteria list is the
/// ordered legend (index 0 = lowest), the answer is a calibrated score
/// over that scale.
final class DecisionScoreQuestion extends DecisionQuestion {
  /// Creates a score question; [criteria] must be non-empty.
  const DecisionScoreQuestion({
    required this.instructions,
    required this.criteria,
  });

  @override
  String get type => 'score';

  @override
  final Object? instructions;

  /// The ordered legend, lowest first.
  @override
  final List<Object?> criteria;
}

/// One typed answer with its calibrated probability.
sealed class DecisionAnswer {
  const DecisionAnswer();

  /// The wire `type` discriminator (mirrors the question's).
  String get type;

  /// The wire form (per-answer shape depends on [type]).
  Map<String, dynamic> toJson();
}

/// The answer to a [DecisionBoolQuestion]: [probability] of `true`
/// (1 - probability is the `false` probability).
final class DecisionBoolAnswer extends DecisionAnswer {
  const DecisionBoolAnswer({required this.probability});

  /// The calibrated probability of `true` (0..1).
  final double probability;

  @override
  String get type => 'bool';

  @override
  Map<String, dynamic> toJson() => {'type': type, 'bool': probability};
}

/// The answer to a [DecisionChoiceQuestion]: the picked option plus the
/// full calibrated probability distribution over all options.
final class DecisionChoiceAnswer extends DecisionAnswer {
  const DecisionChoiceAnswer({
    required this.choice,
    required this.probabilities,
    this.confidence,
  });

  /// The picked option (one of the question's criteria keys).
  final String choice;

  /// The calibrated probability of every option (0..1 each).
  final Map<String, double> probabilities;

  /// The provider's confidence in the pick, when reported.
  final double? confidence;

  @override
  String get type => 'choice';

  @override
  Map<String, dynamic> toJson() => {
    'type': type,
    'choice': choice,
    if (confidence != null) 'confidence': confidence,
    'probabilities': probabilities,
  };
}

/// The answer to a [DecisionScoreQuestion]: a calibrated score over the
/// question's ordered legend.
final class DecisionScoreAnswer extends DecisionAnswer {
  const DecisionScoreAnswer({
    required this.score,
    required this.probabilities,
    this.confidence,
    this.legend,
  });

  /// The calibrated score (position on the legend's scale).
  final double score;

  /// The calibrated probability of every legend index (keys are the
  /// stringified indices), when reported.
  final Map<String, double> probabilities;

  /// The provider's confidence, when reported.
  final double? confidence;

  /// The echoed legend (index → label), when reported.
  final Map<String, Object?>? legend;

  @override
  String get type => 'score';

  @override
  Map<String, dynamic> toJson() => {
    'type': type,
    'score': score,
    if (confidence != null) 'confidence': confidence,
    'probabilities': probabilities,
    if (legend != null) 'legend': legend,
  };
}

/// Usage accounting parsed from the response's `usage` block (present on
/// success responses; every field optional because providers may omit).
final class DecisionUsage {
  const DecisionUsage({this.inputTokens, this.outputTokens, this.cost});

  /// Tokens billed for the state + questions.
  final int? inputTokens;

  /// Tokens billed for the answers.
  final int? outputTokens;

  /// Cost in USD, when reported.
  final double? cost;

  /// The wire form; absent fields stay absent.
  Map<String, dynamic> toJson() => {
    if (inputTokens != null) 'input_tokens': inputTokens,
    if (outputTokens != null) 'output_tokens': outputTokens,
    if (cost != null) 'cost': cost,
  };
}

/// The outcome of one Decisions call — NEVER thrown. Provider errors,
/// malformed responses, and local validation failures all land in
/// [DecisionResult.failure]; only programmer errors (null required
/// arguments) throw.
sealed class DecisionResult {
  const DecisionResult();

  /// True on [DecisionSuccess].
  bool get isSuccess => this is DecisionSuccess;

  /// The structured JSON form surfaced to the model/user.
  Map<String, dynamic> toJson();
}

/// The success variant of [DecisionResult].
final class DecisionSuccess extends DecisionResult {
  const DecisionSuccess({
    this.id,
    this.model,
    this.provider,
    required this.answers,
    required this.usage,
  });

  /// The decision/generation id, when reported.
  final String? id;

  /// The resolved model slug, when reported.
  final String? model;

  /// The serving provider, when reported.
  final String? provider;

  /// The typed answers keyed by question name.
  final Map<String, DecisionAnswer> answers;

  /// Usage accounting.
  final DecisionUsage usage;

  @override
  Map<String, dynamic> toJson() => {
    if (id != null) 'id': id,
    if (model != null) 'model': model,
    if (provider != null) 'provider': provider,
    'answers': {for (final e in answers.entries) e.key: e.value.toJson()},
    'usage': usage.toJson(),
  };
}

/// The failure variant of [DecisionResult]: structured, actionable,
/// never thrown.
final class DecisionFailure extends DecisionResult {
  const DecisionFailure({
    this.statusCode,
    this.code,
    required this.message,
    this.validation = false,
  });

  /// The HTTP status of the failing call, when it reached the wire.
  final int? statusCode;

  /// The provider's error code, when parsed.
  final int? code;

  /// The human-readable failure reason (provider message or local
  /// validation text). Never contains the API key.
  final String message;

  /// True when the failure is local request validation (the call never
  /// hit the network).
  final bool validation;

  @override
  Map<String, dynamic> toJson() => {
    'error': {
      if (statusCode != null) 'statusCode': statusCode,
      if (code != null) 'code': code,
      'message': message,
      if (validation) 'validation': true,
    },
  };
}

/// Validates a decisions request BEFORE any network call; returns the
/// failure result on the first problem (never thrown — gh-1844 AC4
/// "validation ... as result").
DecisionFailure? validateDecisionRequest({
  required String model,
  required Object? state,
  required Map<String, DecisionQuestion> questions,
}) {
  if (model.trim().isEmpty) {
    return const DecisionFailure(
      validation: true,
      message: 'model is required (e.g. inception/mercury-decide:free)',
    );
  }
  if (state == null) {
    return const DecisionFailure(
      validation: true,
      message:
          'state is required — the content the questions decide '
          'about (text, JSON object, or array)',
    );
  }
  if (questions.isEmpty) {
    return const DecisionFailure(
      validation: true,
      message: 'at least one question is required',
    );
  }
  for (final entry in questions.entries) {
    if (entry.key.trim().isEmpty) {
      return const DecisionFailure(
        validation: true,
        message: 'question names must be non-empty',
      );
    }
    final question = entry.value;
    if (question is DecisionChoiceQuestion && question.criteria.isEmpty) {
      return DecisionFailure(
        validation: true,
        message:
            'choice question "${entry.key}" needs non-empty criteria '
            '({option: description})',
      );
    }
    if (question is DecisionScoreQuestion && question.criteria.isEmpty) {
      return DecisionFailure(
        validation: true,
        message:
            'score question "${entry.key}" needs a non-empty criteria '
            'list (ordered legend, lowest first)',
      );
    }
  }
  return null;
}

/// The OpenRouter Decisions adapter (`POST {baseUrl}/systemone`).
///
/// The endpoint is OpenRouter-specific: it is NOT OpenAI-chat-compatible,
/// so this stands next to the provider adapters instead of riding a chat
/// dialect flag. All provider outcomes are structured [DecisionResult]s.
final class DecisionsAdapter {
  /// Creates an adapter; [httpClient] is injectable for fake-HTTP tests.
  const DecisionsAdapter({this.httpClient});

  /// The injected client (a fresh short-lived one per call when null).
  final http.Client? httpClient;

  /// The Decisions API path under an OpenRouter-style base URL
  /// (`https://openrouter.ai/api/v1` → `…/systemone`).
  static const String path = '/systemone';

  /// The default OpenRouter base URL.
  static const String defaultBaseUrl = 'https://openrouter.ai/api/v1';

  /// Asks [questions] about [state] with [model]. Local validation
  /// failures return [DecisionFailure] with `validation: true` BEFORE
  /// any network call; provider failures return the parsed
  /// status/code/message; success returns the typed calibrated answers.
  Future<DecisionResult> decide({
    required String model,
    required Object? state,
    required Map<String, DecisionQuestion> questions,
    String baseUrl = defaultBaseUrl,
    required String apiKey,
  }) async {
    final invalid = validateDecisionRequest(
      model: model,
      state: state,
      questions: questions,
    );
    if (invalid != null) return invalid;

    final client = httpClient ?? http.Client();
    http.Response response;
    try {
      response = await client.post(
        Uri.parse('${_trimSlash(baseUrl)}$path'),
        headers: {
          'Content-Type': 'application/json',
          if (apiKey.isNotEmpty) 'Authorization': 'Bearer $apiKey',
        },
        body: jsonEncode({
          'model': model,
          'state': state,
          'questions': {
            for (final entry in questions.entries)
              entry.key: entry.value.toJson(),
          },
        }),
      );
    } finally {
      if (httpClient == null) client.close();
    }
    return parseDecisionResponse(response.statusCode, response.body);
  }

  /// Parses one Decisions response (2xx success shape or the
  /// `{error: {code, message}}` failure shape). Non-JSON bodies degrade
  /// to a failure naming the HTTP status. Never throws on provider data.
  DecisionResult parseDecisionResponse(int statusCode, String body) {
    Object? decoded;
    try {
      decoded = jsonDecode(body);
    } on FormatException {
      decoded = null;
    }
    if (statusCode < 200 || statusCode >= 300) {
      var code = statusCode;
      var message = 'HTTP $statusCode';
      if (decoded is Map && decoded['error'] is Map) {
        final error = decoded['error'] as Map;
        final parsedCode = error['code'];
        if (parsedCode is int) code = parsedCode;
        final parsedMessage = error['message'];
        if (parsedMessage is String && parsedMessage.isNotEmpty) {
          message = parsedMessage;
        }
      }
      return DecisionFailure(
        statusCode: statusCode,
        code: code,
        message: message,
      );
    }
    if (decoded is! Map<String, dynamic>) {
      return DecisionFailure(
        statusCode: statusCode,
        message: 'decisions response was not a JSON object',
      );
    }
    final answersJson = decoded['answers'];
    if (answersJson is! Map) {
      return DecisionFailure(
        statusCode: statusCode,
        message: 'decisions response carried no answers object',
      );
    }
    final answers = <String, DecisionAnswer>{};
    for (final entry in answersJson.entries) {
      final answer = _parseAnswer(entry.value);
      if (answer == null) {
        return DecisionFailure(
          statusCode: statusCode,
          message:
              'decisions answer "${entry.key}" had an unknown or '
              'malformed shape: ${entry.value}',
        );
      }
      answers[entry.key.toString()] = answer;
    }
    return DecisionSuccess(
      id: decoded['id']?.toString(),
      model: decoded['model']?.toString(),
      provider: decoded['provider']?.toString(),
      answers: answers,
      usage: _parseUsage(decoded['usage']),
    );
  }

  DecisionAnswer? _parseAnswer(Object? value) {
    if (value is! Map) return null;
    final type = value['type'];
    switch (type) {
      case 'bool':
        final probability = _asDouble(value['bool']);
        return probability == null
            ? null
            : DecisionBoolAnswer(probability: probability);
      case 'choice':
        final choice = value['choice'];
        if (choice is! String) return null;
        return DecisionChoiceAnswer(
          choice: choice,
          confidence: _asDouble(value['confidence']),
          probabilities: _probabilityMap(value['probabilities']),
        );
      case 'score':
        final score = _asDouble(value['score']);
        if (score == null) return null;
        final legend = value['legend'];
        return DecisionScoreAnswer(
          score: score,
          confidence: _asDouble(value['confidence']),
          probabilities: _probabilityMap(value['probabilities']),
          legend: legend is Map
              ? legend.map((k, v) => MapEntry(k.toString(), v))
              : null,
        );
      default:
        return null;
    }
  }

  DecisionUsage _parseUsage(Object? value) {
    if (value is! Map) return const DecisionUsage();
    return DecisionUsage(
      inputTokens: _asInt(value['input_tokens']),
      outputTokens: _asInt(value['output_tokens']),
      cost: _asDouble(value['cost']),
    );
  }

  static Map<String, double> _probabilityMap(Object? value) {
    if (value is! Map) return const {};
    return {
      for (final entry in value.entries)
        if (_asDouble(entry.value) != null)
          entry.key.toString(): _asDouble(entry.value)!,
    };
  }

  static double? _asDouble(Object? value) =>
      value is num ? value.toDouble() : null;

  static int? _asInt(Object? value) => value is num ? value.toInt() : null;

  String _trimSlash(String url) =>
      url.endsWith('/') ? url.substring(0, url.length - 1) : url;
}

/// The `decide` tool (gh-1844): structured decisions via OpenRouter's
/// Decisions API (`/v1/systemone`).
///
/// A decision model answers TYPED questions (yes-no / choice / score)
/// about a `state` with CALIBRATED PROBABILITIES — not free text. The
/// tool surfaces the answers as structured JSON the model can act on.
///
/// Endpoint resolution is CAPABILITY-driven: the Decisions API is an
/// OpenRouter product, so the tool rides the MAIN connection when (and
/// only when) the main provider is OpenRouter; any other main provider
/// fails with an actionable error before any network call. The model id
/// is a tool argument (e.g. `inception/mercury-decide:free`) — a new
/// decision model works with zero code changes, exactly like every other
/// capability-driven path.
library;

import 'dart:convert';

import 'package:http/http.dart' as http;

import '../agent/agent_loop.dart' show ToolExecutionResult;
import '../agent/agent_tool.dart';
import '../approval/approval.dart';
import '../decisions/decisions.dart';

/// The `decide` tool name.
const decideToolName = 'decide';

/// Builds the `decide` [AgentTool].
///
/// [mainBaseUrl]/[mainProviderKind]/[mainApiKey] are live accessors (the
/// provider switch applies without a restart), same pattern as the media
/// tools.
AgentTool decideTool({
  required String Function() mainBaseUrl,
  required String Function() mainProviderKind,
  required String Function() mainApiKey,
  http.Client? httpClient,
}) {
  return AgentTool(
    name: decideToolName,
    label: decideToolName,
    tier: ApprovalTier.read,
    description:
        'Ask a structured decision model (OpenRouter Decisions API, '
        'e.g. inception/mercury-decide:free) typed questions about a '
        'state and receive calibrated answers as structured JSON: yes-no '
        'questions come back with a probability, choice questions with '
        'the picked option plus per-option probabilities, score '
        'questions with a calibrated score over the ordered legend. '
        'Requires the main connection to be an OpenRouter provider. '
        'Arguments: model (required), state (required — text or JSON), '
        'questions (required — object keyed by question name; each entry '
        'is {type: bool|choice|score, instructions, criteria}).',
    parameters: const {
      'type': 'object',
      'properties': {
        'model': {
          'type': 'string',
          'description':
              'decision model slug, e.g. inception/mercury-decide:free',
        },
        'state': {
          'description':
              'the content the questions decide about: a string, or a '
              'JSON object/array of related context',
        },
        'questions': {
          'type': 'object',
          'description':
              'typed questions keyed by name, e.g. {"is_bug": '
              '{"type": "bool", "instructions": "Is this a defect?", '
              '"criteria": {"true": "...", "false": "..."}}, "team": '
              '{"type": "choice", "instructions": "Which team?", '
              '"criteria": {"frontend": "...", "payments": "..."}}}',
        },
      },
      'required': ['model', 'state', 'questions'],
    },
    execute: (arguments, cancelToken, onUpdate) async {
      cancelToken?.throwIfCancelled();
      final model = (arguments['model'] as String? ?? '').trim();
      if (!arguments.containsKey('state')) {
        return ToolExecutionResult.text(
          jsonEncode(
            const DecisionFailure(
              validation: true,
              message: 'state is required',
            ).toJson(),
          ),
        );
      }
      final state = arguments['state'];
      final questionsArg = arguments['questions'];
      if (questionsArg is! Map) {
        return ToolExecutionResult.text(
          jsonEncode(
            const DecisionFailure(
              validation: true,
              message:
                  'questions must be an object keyed by question '
                  'name',
            ).toJson(),
          ),
        );
      }
      final questions = <String, DecisionQuestion>{};
      DecisionFailure? parseFailure;
      for (final entry in questionsArg.entries) {
        final parsed = _parseQuestion(entry.value);
        if (parsed == null) {
          parseFailure = DecisionFailure(
            validation: true,
            message:
                'question "${entry.key}" must be an object with a '
                'type of bool, choice, or score (and instructions)',
          );
          break;
        }
        questions[entry.key.toString()] = parsed;
      }
      if (parseFailure != null) {
        return ToolExecutionResult.text(jsonEncode(parseFailure.toJson()));
      }

      // Capability gate: the Decisions API is OpenRouter-only. A
      // non-OpenRouter main connection fails HERE, before any network
      // call — capability-driven, never model-name-driven.
      final provider = mainProviderKind();
      if (provider != 'openrouter') {
        return ToolExecutionResult.text(
          jsonEncode(
            DecisionFailure(
              validation: true,
              message:
                  'the Decisions API is served by OpenRouter, but '
                  'the main connection provider is "$provider" — connect '
                  'an OpenRouter provider to use decide',
            ).toJson(),
          ),
        );
      }

      final adapter = DecisionsAdapter(httpClient: httpClient);
      final result = await adapter.decide(
        model: model,
        state: state,
        questions: questions,
        baseUrl: mainBaseUrl(),
        apiKey: [REDACTED:Sensitive Value]),
      );
      cancelToken?.throwIfCancelled();
      return ToolExecutionResult.text(jsonEncode(result.toJson()));
    },
  );
}

/// Parses one tool-argument question entry into a [DecisionQuestion];
/// null when the shape is unusable (the caller reports it as a
/// validation failure).
DecisionQuestion? _parseQuestion(Object? value) {
  if (value is! Map) return null;
  final type = value['type'];
  final instructions = value['instructions'];
  switch (type) {
    case 'bool':
      final criteria = value['criteria'];
      final map = criteria is Map ? criteria : const <Object?, Object?>{};
      return DecisionBoolQuestion(
        instructions: instructions,
        criteriaTrue: map['true'],
        criteriaFalse: map['false'],
      );
    case 'choice':
      final criteria = value['criteria'];
      if (criteria is! Map) return null;
      return DecisionChoiceQuestion(
        instructions: instructions,
        criteria: criteria.map((k, v) => MapEntry(k.toString(), v)),
      );
    case 'score':
      final criteria = value['criteria'];
      if (criteria is! List) return null;
      return DecisionScoreQuestion(
        instructions: instructions,
        criteria: List<Object?>.from(criteria),
      );
    default:
      return null;
  }
}

